#include <stdio.h>

int main() {
    int N, Q;
    scanf("%d %d", &N, &Q);

    char grid[50][51], next[50][51];

    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    for (int step = 0; step < Q; step++) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int alive = 0;

                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (di == 0 && dj == 0) continue;

                        int ni = i + di;
                        int nj = j + dj;

                        if (ni >= 0 && ni < N && nj >= 0 && nj < N) {
                            if (grid[ni][nj] == '1') {
                                alive++;
                            }
                        }
                    }
                }

                if (grid[i][j] == '1') {
                    if (alive == 2 || alive == 3) {
                        next[i][j] = '1';
                    } else {
                        next[i][j] = '0';
                    }
                } else {
                    if (alive == 3) {
                        next[i][j] = '1';
                    } else {
                        next[i][j] = '0';
                    }
                }
            }
            next[i][N] = '\0';
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j <= N; j++) {
                grid[i][j] = next[i][j];
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
